using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using System.Net.Http.Json;
namespace SportRace.Web.Pages.Admin.Registrations;
public class EditModel:PageModel {private readonly IHttpClientFactory _factory;[BindProperty]public RegistrationEdit Registration{get;set;}=new();public EditModel(IHttpClientFactory factory)=>_factory=factory;public async Task<IActionResult> OnGetAsync(int id){var r=await _factory.CreateClient("SportRaceApi1").GetFromJsonAsync<RegistrationEdit>($"api/registrations/{id}");if(r is null)return NotFound();Registration=r;return Page();}public async Task<IActionResult> OnPostAsync(){var r=await _factory.CreateClient("SportRaceApi1").PutAsJsonAsync($"api/registrations/{Registration.Id}",Registration);return r.IsSuccessStatusCode?RedirectToPage("Index"):Page();}public class RegistrationEdit{public int Id{get;set;}public int ParticipantId{get;set;}public int EventId{get;set;}public int DisciplineId{get;set;}public int CategoryId{get;set;}public int AgeGroupId{get;set;}public string Status{get;set;}="Pending";}}
